const TZ = 'Europe/Helsinki';
const body = (n) => { try { const j = $(n).first().json; return j.statusCode === 200 ? String(j.body || '') : ''; } catch (e) { return ''; } };
const parse = (s, d) => { try { const v = JSON.parse(s); return v || d; } catch (e) { return d; } };
const now = $now.setZone(TZ);
const ymd = (n) => now.plus({ days: n }).toFormat('yyyy-LL-dd');
const msg = $('Telegram Trigger').first().json.message;
const key = Object.keys($input.first().binary || {})[0];
const buf = await this.helpers.getBinaryDataBuffer(0, key);
const SYSTEM = 'You extract vocabulary from a photo of a Finnish textbook page (Suomen Mestari) for an Egyptian-Arabic speaker who also reads English. Return ONLY words clearly visible on the page; skip anything unclear; never invent words. For each word give: fi (base form as printed), ar (short Egyptian Arabic meaning), en (English meaning), example (a short correct Finnish sentence, or empty), mnemonic (one short Arabic sound-alike/picture hint, or empty). chapter: the chapter/kappale if the caption or page says so, else empty.';
const schema = {"type": "object", "properties": {"chapter": {"type": "string"}, "words": {"type": "array", "items": {"type": "object", "properties": {"fi": {"type": "string"}, "ar": {"type": "string"}, "en": {"type": "string"}, "example": {"type": "string"}, "mnemonic": {"type": "string"}}, "required": ["fi", "ar", "en", "example", "mnemonic"], "additionalProperties": false}}}, "required": ["chapter", "words"], "additionalProperties": false};
const request = {
  model: "claude-opus-5-5",
  max_tokens: 4000,
  output_config: { format: { type: 'json_schema', schema } },
  system: SYSTEM,
  messages: [{ role: 'user', content: [
    { type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: buf.toString('base64') } },
    { type: 'text', text: 'Caption: ' + (msg.caption || '') }
  ] }]
};
return [{ json: { body: request } }];

const TZ = 'Europe/Helsinki';
const body = (n) => { try { const j = $(n).first().json; return j.statusCode === 200 ? String(j.body || '') : ''; } catch (e) { return ''; } };
const parse = (s, d) => { try { const v = JSON.parse(s); return v || d; } catch (e) { return d; } };
const now = $now.setZone(TZ);
const ymd = (n) => now.plus({ days: n }).toFormat('yyyy-LL-dd');
const res = $input.first().json;
if (res.error || !Array.isArray(res.content)) throw new Error('Claude error: ' + JSON.stringify(res.error || res).slice(0, 300));
const data = JSON.parse(res.content.filter(c => c.type === 'text').map(c => c.text).join(''));
const state = parse(body('Get vocab'), { words: {} });
if (!state.words) state.words = {};
const added = [], known = [];
for (const w of data.words || []) {
  const key = String(w.fi || '').trim().toLowerCase();
  if (!key) continue;
  if (state.words[key]) { known.push(key); continue; }
  state.words[key] = { fi: w.fi.trim(), ar: w.ar || '', en: w.en || '', example: w.example || '', mnemonic: w.mnemonic || '', chapter: data.chapter || '', box: 1, due: ymd(1), added: ymd(0), lapses: 0, seen: 0 };
  added.push(w);
}
const lines = added.map(w => `• ${w.fi} = ${w.ar} (${w.en})`).join('\n');
const reply = added.length
  ? `✅ ضفت ${added.length} كلمة${data.chapter ? ' من ' + data.chapter : ''}:\n${lines}\n\nهنراجعهم بالتكرار المتباعد. تحب نبدأ بأول كلمة دلوقتي؟`
  : '⚠️ ملقيتش كلمات جديدة واضحة في الصورة' + (known.length ? ' (كلهم متسجلين قبل كده)' : '') + '. ابعت صورة أوضح لصفحة الـ sanasto.';
return [{ json: { reply, payload: JSON.stringify(state, null, 1) } }];

const text = String($('Ingest merge').first().json.reply || '').trim() || '…';
const chat_id = $('Telegram Trigger').first().json.message.chat.id;
const out = [];
let rest = text;
while (rest.length > 3900) {
  let cut = rest.lastIndexOf('\n', 3900);
  if (cut < 1000) cut = 3900;
  out.push(rest.slice(0, cut));
  rest = rest.slice(cut).replace(/^\n+/, '');
}
out.push(rest);
return out.map(t => ({ json: { chat_id, text: t } }));

const TZ = 'Europe/Helsinki';
